#{id}
and pv.is_deleted = 0

select pv.id, pv.product_property_value_id, pv.property_value, sp.product_property_id from marketing_product_spu_property_value pv left join marketing_product_spu_property sp on pv.spu_property_id = sp.id where pv.id in
#{id}
and pv.is_deleted = 0

select marketing_spu_id, spu_property_id, product_property_value_id, property_value, sort from marketing_product_spu_property_value where marketing_spu_id in
#{id}
