select marketing_spu_id from marketing_product_spu_property_value where is_deleted = 0 and product_property_value_id in
#{id}
group by marketing_spu_id having count(id) = #{propertyValuesIdsCount}

select msppv.marketing_product_sku_id from marketing_product_sku_property_value msppv inner join marketing_product_spu_property_value mspv on msppv.marketing_spu_property_value_id = mspv.id where msppv.is_deleted = 0 and mspv.is_deleted = 0 and mspv.product_property_value_id in
#{id}
group by msppv.marketing_product_sku_id having count(msppv.id ) = #{propertyValuesIdsCount}
